use std::fmt::Write as _;

use crate::manifests::Manifests;

/// Renders the Go file `lib/grn` commits: each service's GRN types
/// with their parent types, and each action with the types it applies
/// to (ADR-0143 item 2). The output is not gofmt-aligned, and the
/// command that writes it runs gofmt.
pub fn render_go(manifests: &Manifests) -> String {
    let mut out = String::new();
    out.push_str(
        "// Code generated by policy/crates/manifest from policy/schema; DO NOT EDIT.\n\n\
         package grn\n\n\
         // generatedTypes holds, for each service, the entity types a GRN names,\n\
         // by the GRN type segment.\n\
         var generatedTypes = map[string]map[string]TypeInfo{\n",
    );
    for service in manifests.services() {
        let _ = writeln!(out, "\t{:?}: {{", service.name);
        for entity in &service.entity_types {
            let Some(grn) = &entity.grn else { continue };
            let _ = writeln!(
                out,
                "\t\t{grn:?}: {{Entity: {:?}, Parents: {}}},",
                entity.name,
                go_strings(&entity.parents)
            );
        }
        out.push_str("\t},\n");
    }
    out.push_str(
        "}\n\n\
         // generatedActions holds each action a manifest declares with what it\n\
         // applies to, by its name on the wire.\n\
         var generatedActions = []ActionInfo{\n",
    );
    for service in manifests.services() {
        for action in &service.actions {
            let Some(applies) = &action.applies_to else {
                continue;
            };
            let _ = writeln!(
                out,
                "\t{{Name: {:?}, Principals: {}, Resources: {}}},",
                action.name,
                go_strings(&applies.principals),
                go_strings(&applies.resources)
            );
        }
    }
    out.push_str("}\n");
    out
}

fn go_strings(items: &[String]) -> String {
    let quoted: Vec<String> = items.iter().map(|item| format!("{item:?}")).collect();
    format!("[]string{{{}}}", quoted.join(", "))
}
